package io.knowledgebrain.planning;
import java.util.*;import java.util.concurrent.*;import java.time.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_PLANNING_DATABASE_URL",matches=".+")
class GoalStoreIntegrationTest {
 PGSimpleDataSource ds;JdbcTemplate sql;GoalStore store;String schema;final UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,actor;final String trace="b".repeat(32);final GoalStore.Input input=new GoalStore.Input("Goal"," description\n","NOT_STARTED","2028-02-29");
 @BeforeEach void init(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_PLANNING_DATABASE_URL"));ds.setUser("brain_planning");ds.setPassword(System.getenv("BRAIN_TEST_PLANNING_DATABASE_PASSWORD"));schema="goal_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);store=new GoalStore(ds,Clock.systemUTC());space=ids.next();actor=ids.next();}
 @AfterEach void cleanup(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 String key(){return UUID.randomUUID().toString().replace("-","");}
 void status(int status,Runnable work){assertEquals(status,assertThrows(ResponseStatusException.class,work::run).getStatusCode().value());}
 int count(String table){return sql.queryForObject("SELECT count(*) FROM "+table,Integer.class);}
 @Test void originalCreateRetrySurvivesEditsRetirementAndPrincipalClaim(){String key=key();var first=store.create(space,actor,key,input,trace);assertFalse(first.replay());assertEquals(7,first.goal().goalId().version());assertEquals("2028-02-29",first.goal().targetDate());assertEquals(first.goal(),store.create(space,ids.next(),key,input,trace).goal());var updated=store.change(space,first.goal().goalId(),actor,1,new GoalStore.Input("Changed","","COMPLETED",null),false,trace);assertNull(updated.targetDate());assertEquals(first.goal(),store.create(space,actor,key,input,trace).goal());status(409,()->store.create(space,actor,key,new GoalStore.Input("Different","","NOT_STARTED",null),trace));store.change(space,updated.goalId(),actor,2,null,true,trace);status(404,()->store.get(space,updated.goalId()));assertEquals(first.goal(),store.create(space,ids.next(),key,input,trace).goal());assertTrue(store.list(space,"ALL",null,20).items().isEmpty());assertEquals("RETIRED",store.list(space,"RETIRED","ALL",null,20).items().getFirst().state());assertEquals(1,count("goal"));assertEquals(3,count("goal_revision"));assertEquals(3,count("outbox_event"));assertEquals(List.of(3L,2L,1L),store.history(space,updated.goalId(),Long.MAX_VALUE,5).stream().map(GoalStore.Revision::version).toList());}
 @Test void noopStaleAndForeignReadsNeverPartiallyWrite(){var first=store.create(space,actor,key(),input,trace).goal();assertEquals(first,store.change(space,first.goalId(),actor,1,input,false,trace));status(412,()->store.change(space,first.goalId(),actor,2,input,false,trace));status(404,()->store.get(actor,first.goalId()));status(404,()->store.history(actor,first.goalId(),Long.MAX_VALUE,5));status(404,()->store.change(actor,first.goalId(),actor,1,input,false,trace));assertEquals(1,count("goal_revision"));assertEquals(1,count("outbox_event"));}
 @Test void boundedCatalogFiltersAndIndependentHistoryPages(){var selected=store.create(space,actor,key(),input,trace).goal();for(int i=0;i<22;i++)store.create(space,actor,key(),new GoalStore.Input("Goal "+i,"",i%2==0?"COMPLETED":"NOT_STARTED",null),trace);store.create(actor,actor,key(),input,trace);var a=store.list(space,"ALL",null,20);assertEquals(20,a.items().size());assertNotNull(a.nextAfter());var b=store.list(space,"ALL",a.nextAfter(),20);assertEquals(3,b.items().size());assertNull(b.nextAfter());assertEquals(11,store.list(space,"COMPLETED",null,100).items().size());for(int v=1;v<9;v++)store.change(space,selected.goalId(),actor,v,new GoalStore.Input("Version "+(v+1),"","IN_PROGRESS",null),false,trace);assertEquals(List.of(9L,8L,7L,6L,5L),store.history(space,selected.goalId(),Long.MAX_VALUE,5).stream().map(GoalStore.Revision::version).toList());assertEquals(List.of(4L,3L,2L,1L),store.history(space,selected.goalId(),5,5).stream().map(GoalStore.Revision::version).toList());}
 @Test void sqlDatesRemainExactAtCalendarBoundariesAndInDifferentSessionTimezone(){ds.setOptions("-c TimeZone=America/New_York");for(String date:List.of("0001-01-01","1582-10-10","1582-10-15","9999-12-31")){var goal=store.create(space,actor,key(),new GoalStore.Input("Date "+date,"","NOT_STARTED",date),trace).goal();assertEquals(date,sql.queryForObject("SELECT target_date::text FROM goal WHERE goal_id=?",String.class,goal.goalId()));assertEquals(date,store.list(space,"ALL",null,100).items().stream().filter(v->v.goalId().equals(goal.goalId())).findFirst().orElseThrow().targetDate());}}
 @Test void outboxFailureRollsBackCanonicalAndRevisionWrites(){sql.execute("CREATE FUNCTION fail_goal_outbox() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'controlled outbox failure'; END $$");sql.execute("CREATE TRIGGER fail_goal_outbox BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_goal_outbox()");assertThrows(RuntimeException.class,()->store.create(space,actor,key(),input,trace));assertEquals(0,count("goal"));assertEquals(0,count("goal_revision"));assertEquals(0,count("outbox_event"));}
 @Test void concurrentCreateAndEditRequestsHaveOneCanonicalWinner()throws Exception{String key=key();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CyclicBarrier(2);var a=pool.submit(()->{gate.await();return store.create(space,actor,key,input,trace);});var b=pool.submit(()->{gate.await();return store.create(space,actor,key,input,trace);});var one=a.get();var two=b.get();assertEquals(one.goal(),two.goal());assertNotEquals(one.replay(),two.replay());assertEquals(1,count("goal"));var start=new CyclicBarrier(2);var results=new ArrayList<Future<Integer>>();for(int i=0;i<2;i++){final int n=i;results.add(pool.submit(()->{start.await();try{store.change(space,one.goal().goalId(),actor,1,new GoalStore.Input("Concurrent "+n,"","IN_PROGRESS",null),false,trace);return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));}assertEquals(Set.of(200,412),Set.of(results.get(0).get(),results.get(1).get()));assertEquals(2,count("goal_revision"));assertEquals(2,count("outbox_event"));}}
}
